function openOrder(id){ CUR=id; F.api("/admin/api/print/order?id="+encodeURIComponent(id)).then(function(j){ if(!j.ok){ F.toast(j.error||"Fehler",true); return; } F.openDrawer(detail(j)); var dr=document.getElementById("drawer"); if(dr) dr.classList.add("xl","prx"); setTimeout(prdPaint,60); }); }
