/* Druckdatei wirklich herunterladen (Wunsch Simon 06.11.2026): am iPhone/iPad öffnet die App PDFs sonst nur in der Vorschau –
   dort über das Teilen-Menü („In Dateien sichern“), am Computer als Download mit Dateinamen */
F.action("prdl",function(v){ var i=v.indexOf("|"), id=v.slice(0,i), k=v.slice(i+1); F.toast("Datei wird geladen …");
  fetch("/admin/api/print/file?id="+encodeURIComponent(id)+"&"+(k==="src"?"src=1":"dl=1"),{credentials:"same-origin"}).then(function(r){ if(!r.ok) throw new Error("Datei nicht gefunden");
    var cd=r.headers.get("content-disposition")||"", m=cd.match(/filename\*=UTF-8''([^;]+)/), n=m?decodeURIComponent(m[1]):"druckdatei.pdf"; return r.blob().then(function(b){ return {b:b,n:n}; }); })
  .then(function(x){ var file=null; try{ file=new File([x.b],x.n,{type:x.b.type||"application/pdf"}); }catch(e){}
    var touch=navigator.maxTouchPoints>0&&/iPhone|iPad|Macintosh|Android/.test(navigator.userAgent);
    var save=function(){ var u=URL.createObjectURL(x.b), a=document.createElement("a"); a.href=u; a.download=x.n; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){ URL.revokeObjectURL(u); },60000); F.toast("Heruntergeladen: "+x.n); };
    /* nach dem Laden ist die Tipp-Geste am iPhone oft „verbraucht“ – dann ein zweiter Tipp direkt auf „Teilen“ */
    if(touch&&file&&navigator.canShare&&navigator.canShare({files:[file]})){ navigator.share({files:[file],title:x.n}).catch(function(e){ if(e&&e.name==="AbortError") return;
      F.confirm("Datei ist geladen: "+x.n,"Teilen / In Dateien sichern",function(){ navigator.share({files:[file],title:x.n}).catch(function(){ save(); }); }); }); return; }
    save(); })
  .catch(function(e){ F.toast(e.message||"Download fehlgeschlagen",true); }); });
